import{_ as t,o,c as a,a0 as d}from"./chunks/framework.ChlVJx0I.js";const s="/pi-extensions/assets/usage-tui.DTdobRuw.png",i="/pi-extensions/assets/usage-cli.BbvfvJJk.png",g=JSON.parse('{"title":"usage extension","description":"","frontmatter":{},"headers":[],"relativePath":"extensions/usage.md","filePath":"extensions/usage.md","lastUpdated":1789775493000}'),n={name:"extensions/usage.md"};function r(c,e,l,p,h,u){return o(),a("div",null,[...e[0]||(e[0]=[d('<h1 id="usage-extension" tabindex="-1">usage extension <a class="header-anchor" href="#usage-extension" aria-label="Permalink to &quot;usage extension&quot;">​</a></h1><p>LLM token and cost reporting across all pi sessions: every <code>.jsonl</code> under <code>~/.pi/agent/sessions/</code>, all working directories, including subagent sessions.</p><h2 id="screenshots" tabindex="-1">Screenshots <a class="header-anchor" href="#screenshots" aria-label="Permalink to &quot;Screenshots&quot;">​</a></h2><p>The TUI (<code>/usage</code>) over the fixture session files, all-time window:</p><p><img src="'+s+'" alt="usage TUI"></p><p>The CLI (<code>pi-usage report --month 2026-09</code>):</p><p><img src="'+i+`" alt="usage CLI report"></p><h2 id="what-is-counted" tabindex="-1">What is counted <a class="header-anchor" href="#what-is-counted" aria-label="Permalink to &quot;What is counted&quot;">​</a></h2><p>A usage event is one recorded LLM call:</p><ul><li>an assistant message (its own provider and model)</li><li>a tool result that did nested LLM work (no provider of its own)</li><li>a compaction or branch summary (no provider of its own)</li></ul><p>Forked and cloned sessions copy their ancestor&#39;s lines byte-identical, so each distinct line counts once (ADR 0009). Events without a provider are attributed to the model active at their position in the entry tree (ADR 0008). A partial trailing line in a live session is skipped. Zero-only events (aborted calls, unmeasured work) are dropped: they cannot change a total, and keeping them would render empty rows.</p><h2 id="usage-tui" tabindex="-1">/usage (TUI) <a class="header-anchor" href="#usage-tui" aria-label="Permalink to &quot;/usage (TUI)&quot;">​</a></h2><p>Opens the interactive report. One scan on open, then all filtering happens in memory. Every knob is a key, and the legend at the bottom always shows them:</p><table tabindex="0"><thead><tr><th>Key</th><th>Knob</th><th>Values</th></tr></thead><tbody><tr><td><code>b</code></td><td>time bucket</td><td>day, week, month</td></tr><tr><td><code>w</code></td><td>time window</td><td>7d, 30d, 90d, 1y, all</td></tr><tr><td><code>g</code></td><td>group by</td><td>provider+model, provider, model</td></tr><tr><td><code>p</code></td><td>provider filter</td><td>cycles the providers, none</td></tr><tr><td><code>m</code></td><td>model search</td><td>type a substring</td></tr><tr><td><code>s</code></td><td>sort</td><td>time, tokens, cost</td></tr><tr><td><code>c</code></td><td>columns</td><td>full, compact (cache merged)</td></tr><tr><td><code>d</code> / <code>enter</code></td><td>detail</td><td>raw provider/model pairs under the row</td></tr><tr><td><code>r</code></td><td>rescan</td><td>re-read the session files</td></tr><tr><td><code>j</code> / <code>k</code></td><td>rows</td><td>move the cursor</td></tr><tr><td><code>esc</code></td><td>close</td><td></td></tr></tbody></table><p>Defaults: last 30 days, week buckets, provider+model groups, sorted by time, a grand total row at the bottom.</p><p>Numbers are compact in the TUI: exact under 10,000, then k/M/B (a 12-digit count takes four columns). Exact digits live in the CLI and in <code>--json</code>.</p><p>In headless modes the command prints the same default report: a notify record in RPC mode, the console in print mode.</p><h2 id="usage-report-agent-tool" tabindex="-1">usage_report (agent tool) <a class="header-anchor" href="#usage-report-agent-tool" aria-label="Permalink to &quot;usage_report (agent tool)&quot;">​</a></h2><p>With no arguments it queues <code>/usage</code> so the user gets the TUI. With arguments it returns the report as text:</p><ul><li><code>bucket</code>: <code>day</code> | <code>week</code> | <code>month</code></li><li><code>window</code>: <code>7d</code> | <code>30d</code> | <code>90d</code> | <code>1y</code> | <code>all</code></li><li><code>group</code>: <code>provider</code> | <code>model</code></li></ul><h2 id="pi-usage-cli" tabindex="-1">pi-usage (CLI) <a class="header-anchor" href="#pi-usage-cli" aria-label="Permalink to &quot;pi-usage (CLI)&quot;">​</a></h2><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>pi-usage report [--by day|week|month] [--by provider|model]</span></span>
<span class="line"><span>                [--since 7d|30d|90d|1y|all] [--month YYYY-MM] [--json]</span></span>
<span class="line"><span>pi-usage sessions</span></span>
<span class="line"><span>pi-usage help</span></span></code></pre></div><p>Default report: last 30 days, week buckets, provider+model groups. <code>--json</code> emits rows with the raw provider/model pairs per row. <code>sessions</code> lists every session file with its totals (shared fork history is attributed to the first file scanned).</p><p>On a TTY narrower than 120 columns the report renders the compact column set (cache merged). Piped output always renders the full set.</p><h2 id="canonical-identity" tabindex="-1">Canonical identity <a class="header-anchor" href="#canonical-identity" aria-label="Permalink to &quot;Canonical identity&quot;">​</a></h2><p>Grouping uses a Canonical identity: provider and model folded by a small rule table in <code>lib/identity.ts</code>.</p><ul><li><code>llama.cpp</code>, <code>llama-server=http://127.0.0.1:8080</code>, and <code>crossbar-llamacpp-127-0-0-1-8080</code> are one provider: <code>local-llamacpp</code></li><li><code>omni</code> stays distinct: it is a remote provider with its own billing</li><li>model ids are lowercased, a trailing <code>:QUANT</code> is stripped, and a <code>-GGUF</code> infix is stripped, so <code>unsloth/Qwen3.8-27B-GGUF:Q4_K_XL</code> and <code>unsloth/qwen3.8-27b</code> are one line</li><li>any name no rule touches stays raw</li></ul><p>The <code>d</code> key and <code>--json</code> expose the raw pairs behind each folded row.</p><h2 id="data-path" tabindex="-1">Data path <a class="header-anchor" href="#data-path" aria-label="Permalink to &quot;Data path&quot;">​</a></h2><p>The scan root is <code>~/.pi/agent/sessions/</code>, overridable with the <code>PI_SESSIONS_DIR</code> environment variable (the tests use it to scan fixtures).</p>`,30)])])}const b=t(n,[["render",r]]);export{g as __pageData,b as default};
